static lv_img_dsc_t make_ui_img_placeholder_sensor()
{
    lv_img_dsc_t image = {};
    image.header.always_zero = 0;
    image.header.w = 96;
    image.header.h = 96;
    image.data_size = sizeof(ui_img_placeholder_sensor_data);
    image.header.cf = LV_IMG_CF_TRUE_COLOR_ALPHA;
    image.data = ui_img_placeholder_sensor_data;
    return image;
}

